let model;
self.onmessage=async({data})=>{try{if(!model){self.postMessage({status:'progress',text:'Downloading the open-source model (about 80 MB on first use)…'});const {pipeline,env}=await import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.8.1');env.allowLocalModels=false;env.backends.onnx.wasm.numThreads=1;model=await pipeline('text2text-generation','Xenova/flan-t5-small',{dtype:'q8',device:'wasm',progress_callback:p=>{if(p.status==='progress')self.postMessage({status:'progress',text:`Loading AI: ${p.file} · ${Math.round(p.progress||0)}%`})}})}const out=await model(data.prompt,{max_new_tokens:180,repetition_penalty:1.15,no_repeat_ngram_size:3});self.postMessage({status:'done',text:out[0].generated_text})}catch(e){model=null;self.postMessage({status:'error',text:'The local AI could not load. Check your internet connection and try again. '+e.message})}};
